12	// This file guards the read boundary: real callers may deliver one record
13	// split over several Read calls, or several records in one Read call. As long
14	// as the byte stream and record order are identical, window results, late
15	// notices and the final success/failure must be identical to a one-shot read;
16	// read chunk sizes are not record boundaries.
17	
18	// chunkReader serves the same byte stream as strings.Reader but fixes the size
19	// of each Read: cuts are explicit byte offsets.
20	type chunkReader struct {
21		data []byte
22		cuts []int // cumulative offsets at which a Read ends; the tail is a final read
23		pos  int
24	}
25	
26	func newChunkReader(data string, cuts ...int) *chunkReader {
27		return &chunkReader{data: []byte(data), cuts: cuts}
28	}
29	
30	func (r *chunkReader) Read(p []byte) (int, error) {
31		if r.pos >= len(r.data) {
32			return 0, io.EOF
33		}
34		end := len(r.data)
35		if len(r.cuts) > 0 && r.cuts[0] < end {
36			end = r.cuts[0]
37		}
38		n := copy(p, r.data[r.pos:end])
39		r.pos += n
40		// The cut is reached only once its full prefix has been delivered, so a
41		// small caller buffer simply continues toward the same cut.
42		if len(r.cuts) > 0 && r.pos >= r.cuts[0] {
43			r.cuts = r.cuts[1:]
44		}
45		if r.pos >= len(r.data) {
46			return n, io.EOF
47		}
48		return n, nil
49	}
50	
51	// runChunked executes the partitioned-sliding aggregation with input delivered
52	// in the fixed-size reads described by cuts, returning captured outputs.
53	func runChunked(t *testing.T, input string, cuts []int) (string, string, error) {
54		t.Helper()
55		var out, late bytes.Buffer
56		err := RunAggregatePartitionedSliding(newChunkReader(input, cuts...), 1000, 600, 2, &out, &late)
57		return out.String(), late.String(), err
58	}
59	
60	// canonicalChunkedScenario is the reference stream for partitioned sliding
61	// windows (length 1000ms, slide 600ms, two partitions), one JSON object per
62	// physical line:
63	//
64	//	line 1: partition 0, key 温度, time 700, value 2
65	//	line 2: partition 1, key 温度, time 1000, value 3
66	//	line 3: partition 0 reports watermark 1600 (effective watermark still unknown)
67	//	line 4: partition 1 reports watermark 1000 (min becomes 1000; [0,1000) closes)
68	//	line 5: partition 1, key 温度, time 999, value 9 (late vs effective 1000)
69	//	line 6: partition 1 reports watermark 1600 (min becomes 1600; [600,1600) closes)
70	//
71	// The late event falls in the still-open overlap window [600,1600) but must
72	// not alter it: the window's value 9 never enters any count or sum.
73	func canonicalChunkedScenario() string {
74		return strings.Join([]string{
75			`{"type":"event","key":"温度","time":700,"value":2,"partition":0}`,
76			`{"type":"event","key":"温度","time":1000,"value":3,"partition":1}`,
77			`{"type":"watermark","time":1600,"partition":0}`,
78			`{"type":"watermark","time":1000,"partition":1}`,
79			`{"type":"event","key":"温度","time":999,"value":9,"partition":1}`,
80			`{"type":"watermark","time":1600,"partition":1}`,
81			``,
82		}, "\n")
83	}
84	
85	var canonicalChunkedWindows = strings.Join([]string{
86		`{"key":"温度","start":0,"end":1000,"count":1,"sum":2}`,
87		`{"key":"温度","start":600,"end":1600,"count":2,"sum":5}`,
88		``,
89	}, "\n")
90	
91	const canonicalChunkedLate = "line 5: late event time=999 below current watermark 1000, skipped\n"
92	
93	// allCuts returns every meaningful single-cut partition of a stream (the cut
94	// is the byte length of the first Read), plus the no-cut one-shot read.
95	func allCuts(n int) [][]int {
96		cuts := make([][]int, 0, n)
97		cuts = append(cuts, nil) // one Read carrying every record at once
98		for at := 1; at < n; at++ {
99			cuts = append(cuts, []int{at})
100		}
101		return cuts
102	}
103	
104	// uniformCuts splits a stream into equal-size reads of n bytes (the last read
105	// may be shorter).
106	func uniformCuts(total, n int) []int {
107		var cuts []int
108		for at := n; at < total; at += n {
109			cuts = append(cuts, at)
110		}
111		return cuts
112	}
113	
114	// TestChunkedArrivalBaseline pins the one-shot reference result that every
115	// fragmented/coalesced delivery below must reproduce.
116	func TestChunkedArrivalBaseline(t *testing.T) {
117		var out, late bytes.Buffer
118		if err := RunAggregatePartitionedSliding(strings.NewReader(canonicalChunkedScenario()), 1000, 600, 2, &out, &late); err != nil {
119			t.Fatalf("unexpected error: %v", err)
120		}
121		if out.String() != canonicalChunkedWindows {
122			t.Fatalf("window output mismatch:\n got: %q\nwant: %q", out.String(), canonicalChunkedWindows)
123		}
124		if late.String() != canonicalChunkedLate {
125			t.Fatalf("late notice mismatch:\n got: %q\nwant: %q", late.String(), canonicalChunkedLate)
126		}
127	}
128	
129	// TestChunkedArrivalSingleByteCuts delivers one byte per Read, so the
130	// three-byte UTF-8 encoding of 温度, every JSON field and every newline are
131	// repeatedly split across reads. Results must be byte-identical.
132	func TestChunkedArrivalSingleByteCuts(t *testing.T) {
133		input := canonicalChunkedScenario()
134		cuts := make([]int, 0, len(input)-1)
135		for at := 1; at < len(input); at++ {
136			cuts = append(cuts, at)
137		}
138		out, late, err := runChunked(t, input, cuts)
139		if err != nil {
140			t.Fatalf("single-byte reads must not change the result, got error: %v", err)
141		}
142		if out != canonicalChunkedWindows {
143			t.Fatalf("single-byte reads changed window output:\n got: %q\nwant: %q", out, canonicalChunkedWindows)
144		}
145		if late != canonicalChunkedLate {
146			t.Fatalf("single-byte reads changed late notice:\n got: %q\nwant: %q", late, canonicalChunkedLate)
147		}
148	}
149	
150	// TestChunkedArrivalEveryTwoReadCuts exhaustively splits the stream at one
151	// byte offset using a two-Read delivery (first record may be half a record,
152	// second read may carry several records), covering every multibyte boundary.
153	func TestChunkedArrivalEveryTwoReadCuts(t *testing.T) {
154		input := canonicalChunkedScenario()
155		for _, cuts := range allCuts(len(input)) {
156			cuts := cuts
157			name := "oneshot"
158			if cuts != nil {
159				name = fmt.Sprintf("cut@%d", cuts[0])
160			}
161			t.Run(name, func(t *testing.T) {
162				out, late, err := runChunked(t, input, cuts)
163				if err != nil {
164					t.Fatalf("cut %v: unexpected error: %v", cuts, err)
165				}
166				if out != canonicalChunkedWindows {
167					t.Fatalf("cut %v: window output:\n got: %q\nwant: %q", cuts, out, canonicalChunkedWindows)
168				}
169				if late != canonicalChunkedLate {
170					t.Fatalf("cut %v: late notice:\n got: %q\nwant: %q", cuts, late, canonicalChunkedLate)
171				}
172			})
173		}
174	}
175	
176	// TestChunkedArrivalUniformSizes repeats the whole stream under several fixed
177	// read sizes (one read may bring several records; a record may span many
178	// reads), deliberately including sizes that do not align with record or
179	// multibyte boundaries.
180	func TestChunkedArrivalUniformSizes(t *testing.T) {
181		input := canonicalChunkedScenario()
182		for _, size := range []int{1, 2, 3, 5, 7, 13, 31, 64, 100, 256} {
183			size := size
184			t.Run(fmt.Sprintf("size%d", size), func(t *testing.T) {
185				out, late, err := runChunked(t, input, uniformCuts(len(input), size))
186				if err != nil {
187					t.Fatalf("size %d: unexpected error: %v", size, err)
188				}
189				if out != canonicalChunkedWindows {
190					t.Fatalf("size %d: window output:\n got: %q\nwant: %q", size, out, canonicalChunkedWindows)
191				}
192				if late != canonicalChunkedLate {
193					t.Fatalf("size %d: late notice:\n got: %q\nwant: %q", size, late, canonicalChunkedLate)
194				}
195			})
196		}
197	}
198	
199	// TestChunkedArrivalCutsOnDelimitersAndFields places cuts exactly around the
200	// structural points most tempting to mistake for record boundaries: start and
201	// end of the multibyte key, JSON punctuation, field contents and newlines.
202	func TestChunkedArrivalCutsOnDelimitersAndFields(t *testing.T) {
203		input := canonicalChunkedScenario()
204		cases := map[string][]int{
205			"after each record newline": {
206				len(`{"type":"event","key":"温度","time":700,"value":2,"partition":0}`) + 1,
207				len(`{"type":"event","key":"温度","time":700,"value":2,"partition":0}`) + 1 +
208					len(`{"type":"event","key":"温度","time":1000,"value":3,"partition":1}`) + 1,
209			},
210			"inside every record": func() []int {
211				var cuts []int
212				pos := 0
213				for _, line := range strings.Split(strings.TrimSuffix(input, "\n"), "\n") {
214					mid := pos + len(line)/2 // splits the key bytes for the event records
215					cuts = append(cuts, mid)
216					pos += len(line) + 1
217					cuts = append(cuts, pos-1) // one byte before each newline: '\n' arrives alone
218				}
219				return cuts
220			}(),
221			"newline delivered one byte late": func() []int {
222				var cuts []int
223				pos := 0
224				for _, line := range strings.Split(strings.TrimSuffix(input, "\n"), "\n") {
225					pos += len(line)
226					cuts = append(cuts, pos) // read ends right before '\n'
227					pos++
228					cuts = append(cuts, pos) // read ends right after '\n'
229				}
230				return cuts
231			}(),
232		}
233		for name, cuts := range cases {
234			cuts := cuts
235			t.Run(name, func(t *testing.T) {
236				out, late, err := runChunked(t, input, cuts)
237				if err != nil {
238					t.Fatalf("%s: unexpected error: %v", name, err)
239				}
240				if out != canonicalChunkedWindows {
241					t.Fatalf("%s: window output:\n got: %q\nwant: %q", name, out, canonicalChunkedWindows)
242				}
243				if late != canonicalChunkedLate {
244					t.Fatalf("%s: late notice:\n got: %q\nwant: %q", name, late, canonicalChunkedLate)
245				}
246			})
247		}
248	}
249	
250	// TestChunkedArrivalBlankLinesCountPhysicalLines interleaves blank lines:
251	// they create no records but still consume physical line numbers, so the late
252	// notice must name line 8 regardless of how the bytes are chunked.
253	func TestChunkedArrivalBlankLinesCountPhysicalLines(t *testing.T) {
254		lines := []string{
255			``, // line 1 blank
256			`{"type":"event","key":"温度","time":700,"value":2,"partition":0}`,
257			``, // line 3 blank
258			`{"type":"event","key":"温度","time":1000,"value":3,"partition":1}`,
259			`{"type":"watermark","time":1600,"partition":0}`,
260			`{"type":"watermark","time":1000,"partition":1}`,
261			``, // line 7 blank
262			`{"type":"event","key":"温度","time":999,"value":9,"partition":1}`, // line 8 late
263			`{"type":"watermark","time":1600,"partition":1}`,
264			``, // trailing blank: line 10
265		}
266		input := strings.Join(lines, "\n")
267		wantLate := "line 8: late event time=999 below current watermark 1000, skipped\n"
268	
269		schedule := func(t *testing.T, r io.Reader) (string, string, error) {
270			var out, late bytes.Buffer
271			err := RunAggregatePartitionedSliding(r, 1000, 600, 2, &out, &late)
272			return out.String(), late.String(), err
273		}
274	
275		oneOut, oneLate, err := schedule(t, strings.NewReader(input))
276		if err != nil {
277			t.Fatalf("one-shot: unexpected error: %v", err)
278		}
279		if oneLate != wantLate {
280			t.Fatalf("one-shot late notice:\n got: %q\nwant: %q", oneLate, wantLate)
281		}
282		if oneOut != canonicalChunkedWindows {
283			t.Fatalf("one-shot window output:\n got: %q\nwant: %q", oneOut, canonicalChunkedWindows)
284		}
285	
286		// Single-byte delivery puts every blank-line '\n' in its own read.
287		cuts := make([]int, 0, len(input)-1)
288		for at := 1; at < len(input); at++ {
289			cuts = append(cuts, at)
290		}
291		chunkOut, chunkLate, err := schedule(t, newChunkReader(input, cuts...))
292		if err != nil {
293			t.Fatalf("chunked: unexpected error: %v", err)
294		}
295		if chunkLate != wantLate {
296			t.Fatalf("chunked late notice:\n got: %q\nwant: %q", chunkLate, wantLate)
297		}
298		if chunkOut != oneOut {
299			t.Fatalf("chunked window output:\n got: %q\nwant: %q", chunkOut, oneOut)
300		}
301	}
302	
303	// TestChunkedArrivalCRLFDelimiters uses carriage-return+newline separators and
304	// no trailing newline on the final (window-closing watermark) record. Neither
305	// delimiter style nor the missing final newline may change aggregation, drop
306	// the final watermark, or corrupt the key/fields when split mid-sequence.
307	func TestChunkedArrivalCRLFDelimiters(t *testing.T) {
308		records := []string{
309			`{"type":"event","key":"温度","time":700,"value":2,"partition":0}`,
310			`{"type":"event","key":"温度","time":1000,"value":3,"partition":1}`,
311			`{"type":"watermark","time":1600,"partition":0}`,
312			`{"type":"watermark","time":1000,"partition":1}`,
313			`{"type":"event","key":"温度","time":999,"value":9,"partition":1}`,
314			`{"type":"watermark","time":1600,"partition":1}`, // last complete record, no newline
315		}
316		input := strings.Join(records[:len(records)-1], "\r\n") + "\r\n" + records[len(records)-1]
317	
318		var oneOut, oneLate bytes.Buffer
319		if err := RunAggregatePartitionedSliding(strings.NewReader(input), 1000, 600, 2, &oneOut, &oneLate); err != nil {
320			t.Fatalf("one-shot: unexpected error: %v", err)
321		}
322		if oneOut.String() != canonicalChunkedWindows {
323			t.Fatalf("one-shot window output:\n got: %q\nwant: %q", oneOut.String(), canonicalChunkedWindows)
324		}
325		if oneLate.String() != canonicalChunkedLate {
326			t.Fatalf("one-shot late notice:\n got: %q\nwant: %q", oneLate.String(), canonicalChunkedLate)
327		}
328	
329		// Single-byte reads split '\r' from '\n' and leave the final record unterminated.
330		cuts := make([]int, 0, len(input)-1)
331		for at := 1; at < len(input); at++ {
332			cuts = append(cuts, at)
333		}
334		var chOut, chLate bytes.Buffer
335		if err := RunAggregatePartitionedSliding(newChunkReader(input, cuts...), 1000, 600, 2, &chOut, &chLate); err != nil {
336			t.Fatalf("chunked CRLF: unexpected error: %v", err)
337		}
338		if chOut.String() != canonicalChunkedWindows {
339			t.Fatalf("chunked CRLF window output (final watermark must not be lost):\n got: %q\nwant: %q", chOut.String(), canonicalChunkedWindows)
340		}
341		if chLate.String() != canonicalChunkedLate {
342			t.Fatalf("chunked CRLF late notice:\n got: %q\nwant: %q", chLate.String(), canonicalChunkedLate)
343		}
344	}
345	
346	// failingAfterReader serves its prefix in reads of at most chunk bytes until
347	// exactly failAt bytes have been delivered. The read that reaches failAt
348	// returns the final bytes together with err when errOnBoundary is true;
349	// otherwise it returns them cleanly and the following read (which delivers no
350	// record) fails. Either shape matches how real readers (net.Conn, pipes)
351	// report an upstream failure; the bytes past failAt are never handed out.
352	type failingAfterReader struct {
353		data          []byte
354		pos           int
355		failAt        int
356		err           error
357		chunk         int
358		errOnBoundary bool
359	}
360	
361	var errSentinelChunkedRead = errors.New("synthetic upstream read failure")
362	
363	func (r *failingAfterReader) Read(p []byte) (int, error) {
364		if r.pos >= r.failAt {
365			return 0, r.err
366		}
367		limit := len(p)
368		if r.chunk > 0 && r.chunk < limit {
369			limit = r.chunk
370		}
371		end := r.pos + limit
372		if end > r.failAt {
373			end = r.failAt
374		}
375		n := copy(p, r.data[r.pos:end])
376		r.pos += n
377		if r.pos >= r.failAt && r.errOnBoundary {
378			return n, r.err
379		}
380		return n, nil
381	}
382	
383	// TestChunkedArrivalIncompleteFinalLineIsInputError: a final line with valid
384	// prefix but no closing brace/newline is an input error on that physical line,
385	// whether it arrives whole or unterminated or one byte at a time. Previously
386	// written windows stay; still-open windows are not emitted.
387	func TestChunkedArrivalIncompleteFinalLineIsInputError(t *testing.T) {
388		complete := strings.Join([]string{
389			`{"type":"event","key":"温度","time":700,"value":2,"partition":0}`,
390			`{"type":"event","key":"温度","time":1000,"value":3,"partition":1}`,
391			`{"type":"watermark","time":1600,"partition":0}`,
392			`{"type":"watermark","time":1000,"partition":1}`, // line 4 closes [0,1000)
393			``,
394		}, "\n")
395		// Line 5 is unterminated JSON (deliberately missing the closing brace).
396		input := complete + `{"type":"watermark","time":1600,"partition":1`
397		wantFirstWindow := `{"key":"温度","start":0,"end":1000,"count":1,"sum":2}` + "\n"
398	
399		check := func(t *testing.T, r io.Reader) {
400			var out, late bytes.Buffer
401			err := RunAggregatePartitionedSliding(r, 1000, 600, 2, &out, &late)
402			var ie *InputError
403			if !errors.As(err, &ie) {
404				t.Fatalf("expected *InputError, got %T: %v", err, err)
405			}
406			if ie.Line != 5 {
407				t.Errorf("InputError.Line = %d, want physical line 5", ie.Line)
408			}
409			if !strings.Contains(ie.Reason, "invalid JSON") {
410				t.Errorf("reason = %q, want invalid JSON", ie.Reason)
411			}
412			if out.String() != wantFirstWindow {
413				t.Errorf("previously emitted windows must be retained and open ones not emitted:\n got: %q\nwant: %q", out.String(), wantFirstWindow)
414			}
415			if late.String() != "" {
416				t.Errorf("no late events in this stream, got %q", late.String())
417			}
418		}
419	
420		t.Run("one-shot unterminated", func(t *testing.T) {
421			check(t, strings.NewReader(input))
422		})
423		t.Run("one byte per read", func(t *testing.T) {
424			cuts := make([]int, 0, len(input)-1)
425			for at := 1; at < len(input); at++ {
426				cuts = append(cuts, at)
427			}
428			check(t, newChunkReader(input, cuts...))
429		})
430		t.Run("incomplete bytes separate from newline", func(t *testing.T) {
431			// Deliver the four complete lines, then the partial line a few bytes at a time.
432			check(t, newChunkReader(input, len(complete), len(complete)+1, len(complete)+5, len(complete)+12))
433		})
434	}
435	
436	// TestChunkedArrivalReadErrorAfterCompleteRecordsPropagates: once several
437	// complete, valid records have been delivered, a Read failure must surface as
438	// the reader's own error (not a silent clean EOF). Completed window output
439	// stays; open windows are not emitted at the failure.
440	func TestChunkedArrivalReadErrorAfterCompleteRecordsPropagates(t *testing.T) {
441		records := []string{
442			`{"type":"event","key":"温度","time":700,"value":2,"partition":0}`,
443			`{"type":"event","key":"温度","time":1000,"value":3,"partition":1}`,
444			`{"type":"watermark","time":1600,"partition":0}`,
445			`{"type":"watermark","time":1000,"partition":1}`,                 // line 4 closes [0,1000)
446			`{"type":"event","key":"温度","time":999,"value":9,"partition":1}`, // line 5 late, then read fails
447			`{"type":"watermark","time":1600,"partition":1}`,                 // must never be reached
448		}
449		full := strings.Join(records, "\n")
450		goodBoundary := len(strings.Join(records[:5], "\n")) + 1 // through line 5 and its '\n'
451	
452		check := func(t *testing.T, r io.Reader) {
453			var out, late bytes.Buffer
454			err := RunAggregatePartitionedSliding(r, 1000, 600, 2, &out, &late)
455			if !errors.Is(err, errSentinelChunkedRead) {
456				t.Fatalf("error must be the reader's original error, got %T: %v", err, err)
457			}
458			if _, ok := err.(*InputError); ok {
459				t.Fatalf("a read failure must not be reported as an *InputError: %v", err)
460			}
461			wantOut := `{"key":"温度","start":0,"end":1000,"count":1,"sum":2}` + "\n"
462			if out.String() != wantOut {
463				t.Errorf("completed output retained, open [600,1600) not emitted:\n got: %q\nwant: %q", out.String(), wantOut)
464			}
465			if late.String() != canonicalChunkedLate {
466				t.Errorf("late notice before the failure must be written:\n got: %q\nwant: %q", late.String(), canonicalChunkedLate)
467			}
468		}
469	
470		t.Run("error alone on the next read", func(t *testing.T) {
471			// The read completing line 5 succeeds; the very next read fails having
472			// delivered nothing.
473			check(t, &failingAfterReader{data: []byte(full), failAt: goodBoundary, err: errSentinelChunkedRead})
474		})
475		t.Run("last good bytes and error together", func(t *testing.T) {
476			// One read returns line 5's trailing newline together with the error,
477			// as a net.Conn may. The complete record still counts; the error wins.
478			check(t, &failingAfterReader{data: []byte(full), failAt: goodBoundary, err: errSentinelChunkedRead, errOnBoundary: true})
479		})
480		t.Run("one byte per read before failure", func(t *testing.T) {
481			// Fragmented delivery up to the boundary, last byte plus error; the
482			// result must be identical to a large-buffer read.
483			check(t, &failingAfterReader{data: []byte(full), failAt: goodBoundary, err: errSentinelChunkedRead, chunk: 1, errOnBoundary: true})
484		})
485	}
486	
487	// TestChunkedArrivalDiscriminatesCorrectAggregates ensures the invariant tests
488	// above would actually fail on the regressions they target: missed counts,
489	// double counting, and a late event admitted into the still-open overlap
490	// window all change the output even when the input is delivered one byte at a
491	// time. This is a characterization guard for the assertions used throughout
492	// the file (expected outputs are computed from the spec, not echoed back).
493	func TestChunkedArrivalDiscriminatesCorrectAggregates(t *testing.T) {
494		type window struct {
495			key        string
496			start, end int64
497			count      int64
498			sum        int64
499		}
500		correct := []window{
501			{"温度", 0, 1000, 1, 2},
502			{"温度", 600, 1600, 2, 5},
503		}
504		missedSecondEvent := []window{
505			{"温度", 0, 1000, 1, 2},
506			{"温度", 600, 1600, 1, 2}, // event time=1000 lost
507		}
508		doubleFirstEvent := []window{
509			{"温度", 0, 1000, 2, 4}, // time=700 counted twice
510			{"温度", 600, 1600, 3, 7},
511		}
512		lateAdmitted := []window{
513			{"温度", 0, 1000, 1, 2},
514			{"温度", 600, 1600, 3, 14}, // late time=999/value=9 wrongly added
515		}
516		render := func(ws []window) string {
517			var b strings.Builder
518			for _, w := range ws {
519				fmt.Fprintf(&b, `{"key":%q,"start":%d,"end":%d,"count":%d,"sum":%d}`+"\n", w.key, w.start, w.end, w.count, w.sum)
520			}
521			return b.String()
522		}
523		want := render(correct)
524		if want != canonicalChunkedWindows {
525			t.Fatalf("test harness render drifted from the pinned expectation:\n got: %q\nwant: %q", want, canonicalChunkedWindows)
526		}
527		for name, ws := range map[string][]window{
528			"missed event":  missedSecondEvent,
529			"double count":  doubleFirstEvent,
530			"late admitted": lateAdmitted,
531		} {
532			if got := render(ws); got == want {
533				t.Fatalf("mutated scenario %q unexpectedly matched the correct output", name)
534			}
535		}
536	
537		// End-to-end: deliver the real stream one byte at a time and confirm the
538		// late value 9 never appears in any aggregate sum.
539		input := canonicalChunkedScenario()
540		cuts := make([]int, 0, len(input)-1)
541		for at := 1; at < len(input); at++ {
542			cuts = append(cuts, at)
543		}
544		out, _, err := runChunked(t, input, cuts)
545		if err != nil {
546			t.Fatalf("unexpected error: %v", err)
547		}
548		if strings.Contains(out, `"sum":14`) || strings.Contains(out, `"sum":9`) {
549			t.Fatalf("late event value leaked into a window: %q", out)
550		}
551	}
552	
553	// TestChunkedArrivalAcrossEntryPoints repeats the fragmentation invariant for
554	// the other public entry shapes, so read-batching can never become a record
555	// boundary in fixed/sliding/partitioned-only modes either.
556	func TestChunkedArrivalAcrossEntryPoints(t *testing.T) {
557		type fixture struct {
558			name string
559			run  func(io.Reader, io.Writer, io.Writer) error
560			in   string
561			want string
562		}
563		events := func(records ...string) string { return strings.Join(records, "\n") + "\n" }
564	
565		fixed := events(
566			`{"type":"event","key":"温度","time":100,"value":2}`,
567			`{"type":"event","key":"温度","time":200,"value":3}`,
568			`{"type":"watermark","time":1000}`,
569		)
570		sliding := events(
571			`{"type":"event","key":"温度","time":700,"value":2}`,
572			`{"type":"watermark","time":1000}`,
573		)
574		partitioned := events(
575			`{"type":"event","key":"温度","time":100,"value":2,"partition":0}`,
576			`{"type":"event","key":"温度","time":200,"value":3,"partition":1}`,
577			`{"type":"watermark","time":1000,"partition":0}`,
578			`{"type":"watermark","time":1000,"partition":1}`,
579		)
580		fxs := []fixture{
581			{"fixed", func(r io.Reader, o, l io.Writer) error { return RunAggregate(r, 1000, o, l) }, fixed,
582				`{"key":"温度","start":0,"end":1000,"count":2,"sum":5}` + "\n"},
583			{"sliding", func(r io.Reader, o, l io.Writer) error { return RunAggregateSliding(r, 1000, 600, o, l) }, sliding,
584				`{"key":"温度","start":0,"end":1000,"count":1,"sum":2}` + "\n"},
585			{"partitioned", func(r io.Reader, o, l io.Writer) error { return RunAggregatePartitioned(r, 1000, 2, o, l) }, partitioned,
586				`{"key":"温度","start":0,"end":1000,"count":2,"sum":5}` + "\n"},
587		}
588	
589		for _, fx := range fxs {
590			fx := fx
591			t.Run(fx.name, func(t *testing.T) {
592				// Reference one-shot result.
593				var refOut, refLate bytes.Buffer
594				if err := fx.run(strings.NewReader(fx.in), &refOut, &refLate); err != nil {
595					t.Fatalf("one-shot: unexpected error: %v", err)
596				}
597				if refOut.String() != fx.want {
598					t.Fatalf("one-shot output:\n got: %q\nwant: %q", refOut.String(), fx.want)
599				}
600				// Every two-read cut and several uniform sizes.
601				schedules := append(allCuts(len(fx.in)),
602					uniformCuts(len(fx.in), 1),
603					uniformCuts(len(fx.in), 3),
604					uniformCuts(len(fx.in), 7),
605				)
606				for _, cuts := range schedules {
607					var out, late bytes.Buffer
608					if err := fx.run(newChunkReader(fx.in, cuts...), &out, &late); err != nil {
609						t.Fatalf("cuts %v: unexpected error: %v", cuts, err)
610					}
611					if out.String() != refOut.String() {
612						t.Fatalf("cuts %v: window output:\n got: %q\nwant: %q", cuts, out.String(), refOut.String())
613					}
614					if late.String() != refLate.String() {
615						t.Fatalf("cuts %v: late output:\n got: %q\nwant: %q", cuts, late.String(), refLate.String())
616					}
617				}
618			})
619		}
620	}
