136	// combinedEOFFailure is a combined error whose chain contains io.EOF
137	// alongside a distinct failure cause, as some readers (multiplexed streams,
138	// wrapped connections) report when an upstream failure coincides with the
139	// local end. errors.Is matches both, but it is not a clean end.
140	type combinedEOFFailure struct {
141		cause error
142	}
143	
144	func (e *combinedEOFFailure) Error() string { return "read failure at end: " + e.cause.Error() }
145	func (e *combinedEOFFailure) Unwrap() []error {
146		return []error{io.EOF, e.cause}
147	}
148	
149	// wrappedEOF is io.EOF carried in a fmt %w wrapper.
150	func wrappedEOF() error { return fmt.Errorf("connection reset at end: %w", io.EOF) }
151	
152	// TestReadAggregateLinesBareEOFOnly: the end-of-input rule must accept only
153	// the bare io.EOF sentinel. A wrapped io.EOF and a combined error containing
154	// io.EOF are read failures: the unterminated tail is dropped and the reader's
155	// own error is returned with its chain intact.
156	func TestReadAggregateLinesBareEOFOnly(t *testing.T) {
157		t.Run("wrapped io.EOF is a failure and drops the tail", func(t *testing.T) {
158			input := "first\nsecond\ntail-without-newline"
159			readErr := wrappedEOF()
160			got, err := collectLines(t, &failingAfterReader{
161				data: []byte(input), failAt: len(input),
162				err: readErr, errOnBoundary: true,
163			})
164			if err != readErr {
165				t.Fatalf("error = %v, want the reader's original error unchanged", err)
166			}
167			if !errors.Is(err, io.EOF) {
168				t.Fatalf("wrapped error must stay reachable via errors.Is: %v", err)
169			}
170			want := []collectedLine{{"first", 1}, {"second", 2}}
171			if fmt.Sprint(got) != fmt.Sprint(want) {
172				t.Fatalf("lines = %v, want only newline-terminated lines %v", got, want)
173			}
174		})
175		t.Run("combined error containing io.EOF is a failure and drops the tail", func(t *testing.T) {
176			input := "first\nsecond\ntail-without-newline"
177			readErr := &combinedEOFFailure{cause: errSentinelChunkedRead}
178			got, err := collectLines(t, &failingAfterReader{
179				data: []byte(input), failAt: len(input),
180				err: readErr, errOnBoundary: true,
181			})
182			if err != readErr {
183				t.Fatalf("error = %v, want the reader's original combined error unchanged", err)
184			}
185			if !errors.Is(err, io.EOF) {
186				t.Fatalf("errors.Is must still follow the chain to io.EOF: %v", err)
187			}
188			if !errors.Is(err, errSentinelChunkedRead) {
189				t.Fatalf("errors.Is must reach the actual failure cause: %v", err)
190			}
191			want := []collectedLine{{"first", 1}, {"second", 2}}
192			if fmt.Sprint(got) != fmt.Sprint(want) {
193				t.Fatalf("lines = %v, want only newline-terminated lines %v", got, want)
194			}
195		})
196		t.Run("combined error still completes co-delivered newline lines", func(t *testing.T) {
197			input := strings.Join([]string{
198				`{"type":"event","key":"k","time":100,"value":2}`,
199				`{"type":"watermark","time":1000}`,
200				`{"type":"event","key":"k","time":900,"value":3}`, // unterminated tail
201			}, "\n")
202			readErr := &combinedEOFFailure{cause: errSentinelChunkedRead}
203			var out, late bytes.Buffer
204			err := RunAggregate(&failingAfterReader{
205				data: []byte(input), failAt: len(input),
206				err: readErr, errOnBoundary: true,
207			}, 1000, &out, &late)
208			if err != readErr {
209				t.Fatalf("error = %v, want the combined read error unchanged", err)
210			}
211			wantWindow := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
212			if out.String() != wantWindow {
213				t.Fatalf("the newline-terminated watermark must close the window first:\n got: %q\nwant: %q", out.String(), wantWindow)
214			}
215			if late.String() != "" {
216				t.Fatalf("unterminated tail must not produce late notices: %q", late.String())
217			}
218		})
219	}
