298	// TestReadAggregateErrorUnterminatedTailIsNotARecord drives the exact scenario
299	// from the fix: length-1000 windows, event key=k time=100 value=2 with a
300	// newline, then a time=1000 watermark JSON without a newline, and the reader
301	// fails. The watermark must not close [0,1000); a malformed tail must not be
302	// reported as an input error either -- the read failure is what surfaces.
303	func TestReadAggregateErrorUnterminatedTailIsNotARecord(t *testing.T) {
304		event := `{"type":"event","key":"k","time":100,"value":2}` + "\n"
305		watermark := `{"type":"watermark","time":1000}`
306	
307		cases := []struct {
308			name string
309			tail string
310		}{
311			{"complete-looking watermark tail", watermark},
312			{"truncated watermark tail", `{"type":"watermark","time":1000`},
313			{"garbage tail", `{"type":wate`},
314		}
315		deliveries := []struct {
316			name           string
317			errOnBoundary  bool
318			chunk          int
319			errorAfterTail bool
320		}{
321			{"error on the next read", false, 0, true},
322			{"tail bytes and error in one read", true, 1 << 20, false},
323			{"one byte per read, error with last byte", true, 1, false},
324		}
325		for _, tc := range cases {
326			for _, dl := range deliveries {
327				name := tc.name + "/" + dl.name
328				t.Run(name, func(t *testing.T) {
329					input := event + tc.tail
330					var r io.Reader
331					if dl.errorAfterTail {
332						// The read carrying the tail succeeds; the following read fails.
333						r = &failingAfterReader{data: []byte(input), failAt: len(input), err: errSentinelChunkedRead}
334					} else {
335						r = &failingAfterReader{data: []byte(input), failAt: len(input), err: errSentinelChunkedRead, errOnBoundary: dl.errOnBoundary, chunk: dl.chunk}
336					}
337					var out, late bytes.Buffer
338					err := RunAggregate(r, 1000, &out, &late)
339					if !errors.Is(err, errSentinelChunkedRead) {
340						t.Fatalf("error = %T %v, want the reader's original error via errors.Is", err, err)
341					}
342					if _, ok := err.(*InputError); ok {
343						t.Fatalf("read failure must not be masked by a JSON/input error: %v", err)
344					}
345					if out.String() != "" {
346						t.Fatalf("unterminated watermark must not close a window, stdout = %q", out.String())
347					}
348					if late.String() != "" {
349						t.Fatalf("unterminated tail must not produce late notices: %q", late.String())
350					}
351				})
352			}
353		}
354	}
